import base64, json, os, pathlib, subprocess, zlib

PAYLOAD = '[... ELLIPSIZATION ...]' 

def run(*args):
    subprocess.run(args, check=True)

def main():
    root=pathlib.Path('.').resolve()
    data=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)).decode('utf-8'))
    for rel, content in data.items():
        p=root/rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(content, encoding='utf-8')
    pathlib.Path('bootstrap_repo.py').unlink(missing_ok=True)
    run('git','config','user.name','github-actions[bot]')
    run('git','config','user.email','41898282+github-actions[bot]@users.noreply.github.com')
    run('git','add','-A')
    status=subprocess.run(['git','status','--porcelain'],check=True,capture_output=True,text=True).stdout.strip()
    if status:
        run('git','commit','-m','Add federated trustworthy digital-twin CPS research framework')
        run('git','push','origin','HEAD:main')

if __name__ == '__main__':
    main()
